// Generated by AI

using UnityEngine;

public class PauseMenuController : MonoBehaviour
{
    [Header("Menus")]
    [SerializeField] private GameObject pauseMenu;
    [SerializeField] private GameObject mainMenu;
    [SerializeField] private GameObject settingsMenu;

    [Header("Audio")]
    [SerializeField] private AudioClip openMenuClip;
    [SerializeField] private AudioClip closeMenuClip;

    [SerializeField] private AudioSource menuMusic;
    [SerializeField] private AudioSource playButtonSound;
    [SerializeField] private AudioSource pollutedEnvironmentAudio;

    private AudioSource audioSource;
    private Animator mainMenuAnimator;

    public static bool GameStarted = false;
    private bool openedFromPauseMenu = false;

    private void Start()
    {
        audioSource = GetComponent<AudioSource>();

        if (mainMenu != null)
        {
            mainMenuAnimator = mainMenu.GetComponent<Animator>();
        }

        GameStarted = false;
        Time.timeScale = 0f;

        if (pollutedEnvironmentAudio != null)
        {
            pollutedEnvironmentAudio.Stop();
        }

        if (mainMenuAnimator != null)
        {
            mainMenuAnimator.enabled = false;
        }

        // Initialize menu visibility.
        if (mainMenu != null)
        {
            mainMenu.SetActive(true);
        }

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(false);
        }

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(false);
        }

        // Play the main menu music.
        if (menuMusic != null && !menuMusic.isPlaying)
        {
            menuMusic.Play();
        }
    }

    private void PlayOpenSound()
    {
        if (audioSource != null && openMenuClip != null)
        {
            audioSource.PlayOneShot(openMenuClip);
        }
    }

    private void PlayCloseSound()
    {
        if (audioSource != null && closeMenuClip != null)
        {
            audioSource.PlayOneShot(closeMenuClip);
        }
    }

    // Starts the game and resumes gameplay time.
    public void StartGame()
    {
        GameStarted = true;
        Time.timeScale = 1f;

        if (playButtonSound != null)
        {
            playButtonSound.Play();
        }

        if (menuMusic != null)
        {
            menuMusic.Stop();
        }

        if (pollutedEnvironmentAudio != null)
        {
            pollutedEnvironmentAudio.Play();
        }

        if (mainMenu != null)
        {
            mainMenu.SetActive(false);
        }
    }

    // MAIN MENU

    public void OpenMainMenu()
    {
        PlayOpenSound();

        if (mainMenu != null)
        {
            mainMenu.SetActive(true);
        }

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(false);
        }

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(false);
        }

        if (mainMenuAnimator != null)
        {
            mainMenuAnimator.enabled = true;
        }
    }

    public void CloseMainMenu()
    {
        // Prevent closing the main menu before the game starts.
        if (!GameStarted)
            return;

        PlayCloseSound();

        if (mainMenu != null)
        {
            mainMenu.SetActive(false);
        }
    }

    // SETTINGS MENU

    public void OpenSettingsFromMain()
    {
        PlayOpenSound();

        openedFromPauseMenu = false;

        if (mainMenu != null)
        {
            mainMenu.SetActive(false);
        }

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(true);
        }
    }

    public void OpenSettingsFromPause()
    {
        PlayOpenSound();

        openedFromPauseMenu = true;

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(false);
        }

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(true);
        }
    }

    public void CloseSettingsMenu()
    {
        PlayCloseSound();

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(false);
        }

        if (openedFromPauseMenu)
        {
            if (pauseMenu != null)
            {
                pauseMenu.SetActive(true);
            }
        }
        else
        {
            if (mainMenu != null)
            {
                mainMenu.SetActive(true);
            }
        }
    }

    // PAUSE MENU

    public void OpenPauseMenu()
    {
        // Prevent pausing before the game starts.
        if (!GameStarted)
            return;

        PlayOpenSound();

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(true);
        }
    }

    public void ClosePauseMenu()
    {
        PlayCloseSound();

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(false);
        }
    }
}
